def longest_sequence_of_ones(n):
    max_sequence = current_sequence = 0
    while n:
        if n & 1:
            current_sequence += 1
            max_sequence = max(max_sequence, current_sequence)
        else:
            current_sequence = 0
        n >>= 1
    return max_sequence
```

def longest_common_prefix(strs):
    if not strs:
        return ''
    shortest = min(strs, key=len)
    for i, char in enumerate(shortest):
        for other in strs:
            if other[i] != char:
                return shortest[:i]
    return shortest

Here is the C++ function that merges two sorted lists into a single sorted list:

```cpp
#include <vector>

std::vector<int> merge(const std::vector<int>& list1, const std::vector<int>& list2) {
    std::vector<int> result;
    size_t i1 = 0, i2 = 0;

    while (i1 < list1.size() && i2 < list2.size()) {
        if (list1[i1] < list2[i2]) {
            result.push_back(list1[i1]);
            ++i1;
        } else if (list1[i1] >= list2[i2]) {
            result.push_back(list2[i2]);
            ++i2;
        }
    }

    while (i1 < list1.size()) {
        result.push_back(list1[i1]);
        ++i1;
    }

    while (i2 < list2.size()) {
        result.push_back(list2[i2]);
        ++i2;
    }

    return result;
}
```

This function uses two pointers to iterate through both lists and appends the smaller element to the result list. Once one list is exhausted, the remaining elements of the other list are appended.

