def reward(context, completion):
    reward = 0  # Default reward value

    # Check if the completion is 'Hello, World!'
    if completion.strip() == 'Hello, World!':
        reward = 100000  # Maximum reward
    elif completion.strip() == '':
        reward = -100000  # Minimum reward for empty completion
    else:
        # Reward based on length, but penalize incorrect output
        reward = len(completion) * 10  # Reward based on length
        if 'Hello, World!' not in completion:
            reward -= 50000  # Penalize if 'Hello, World!' is not present

    # Clip reward to the allowed range
    return max(-100000, min(100000, reward))

def reward(context, completion):
    # We reward the model for writing code that is concise and directly answers the question
    # We penalize it for being verbose or adding irrelevant content
    answer_position = completion.find('```python')
    if answer_position == -1:
        return -10000  # No code block found
    code_start = answer_position + len('```python')
    code_lines = completion[code_start:].strip().split('\n')
    code_lines = [line.strip() for line in code_lines if line.strip() and not line.startswith('#')]
    if len(code_lines) > 5:
        return -10000  # Too many lines
    if any('import' in line for line in code_lines):
        return -10000  # No imports allowed
    if completion.count('def') < 1:
        return -10000  # No function defined
    return 100000 / max(1, len(code_lines))  # Reward for concise code

