def reward(context, completion):
    # Calculate the reward based on the length of the completion
    # Encourage concise and complete answers
    reward = max(0, 100000 - (len(completion) - len(context)) * 1000)
    return min(reward, 100000)

def reward(context, completion):
    # Simple reward function that gives a positive reward for completions that are longer than the context
    # and contains the word 'python'
    if len(completion) > len(context) and 'python' in completion.lower():
        return 1000  # Arbitrary positive reward
    elif len(completion) < len(context):
        return -1000  # Arbitrary negative reward
    else:
        return 0

